import {salon,services,looks,dateKey,slotsForDate} from './data.js';
const $=(selector,root=document)=>root.querySelector(selector), $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const safe=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('#year').textContent=new Date().getFullYear(); $$('.directions').forEach(a=>a.href=salon.directions);
$('.menu-toggle').addEventListener('click',()=>{const open=$('#nav').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',String(open));});
$$('#nav a,#nav button').forEach(a=>a.addEventListener('click',()=>{$('#nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');}));
function renderServices(filter='All'){$('#service-grid').innerHTML=services.filter(s=>filter==='All'||s.category===filter).map(s=>`<article class="service-card"><span class="service-num">0${services.indexOf(s)+1} / ${s.category.toUpperCase()}</span><h3>${s.name}</h3><p>${s.description}</p><button class="text-link" data-book-service="${s.id}">Make it my next look <span>↗</span></button></article>`).join('');}
function renderLooks(filter='All'){$('#look-grid').innerHTML=looks.filter(l=>filter==='All'||l.type===filter).map(l=>`<button class="look-card" data-look="${l.id}" aria-label="Explore ${l.name}"><div class="photo look-photo panel-${l.panel}" role="img" aria-label="${l.name} editorial hairstyle inspiration"><span class="zoom" aria-hidden="true">↗</span></div><div class="look-caption"><strong>${l.name}</strong><small>${l.type}</small></div></button>`).join('');}
function bindFilters(group,attr,render){$(group).addEventListener('click',e=>{const b=e.target.closest(`[${attr}]`);if(!b)return;$$('button',$(group)).forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active));});render(b.getAttribute(attr));});}
renderServices();renderLooks();bindFilters('#service-filters','data-service-filter',renderServices);bindFilters('#look-filters','data-look-filter',renderLooks);
let lastFocus=null;function openDialog(dialog){lastFocus=document.activeElement;dialog.showModal();document.body.classList.add('modal-open');$('.close',dialog)?.focus();}
$$('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target.closest('[data-close]'))d.close();else if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});d.addEventListener('close',()=>{if(!$$('dialog[open]').length)document.body.classList.remove('modal-open');lastFocus?.focus();if(d.id==='booking'){state={};$('#booking-content').replaceChildren();}});});
$('#privacy-open').addEventListener('click',()=>openDialog($('#privacy')));
let state={},step=0;const booking=$('#booking');
function startBooking(serviceId='',look=''){state={serviceId,look,date:'',time:'',name:'',email:'',notes:''};step=0;renderStep();openDialog(booking);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-book],[data-book-service]');if(b)startBooking(b.dataset.bookService||'');const lookButton=e.target.closest('[data-look]');if(lookButton){const l=looks.find(x=>x.id===lookButton.dataset.look);$('#look-detail').innerHTML=`<div class="photo look-detail-photo panel-${l.panel}" role="img" aria-label="${l.name} concept hairstyle"></div><div class="look-detail-copy"><h3 id="look-title">${l.name}</h3><p>${l.note}</p><p class="fine-print">AI-generated inspiration. Actual results and service options require a stylist consultation.</p><button class="button" data-use-look="${l.id}">Bring this inspiration <span>↗</span></button></div>`;openDialog($('#look-dialog'));}const use=e.target.closest('[data-use-look]');if(use){const l=looks.find(x=>x.id===use.dataset.useLook);$('#look-dialog').close();startBooking(l.type==='Cuts'?'cut':l.type==='Color'?'highlights':'perm',l.name);}});
function renderStep(){ $('#booking-error').textContent='';$$('.steps li').forEach((l,i)=>l.classList.toggle('active',i===step));$('#booking-back').hidden=step===0;$('#booking-next').textContent=step===2?'Complete demo →':'Continue →';$('.booking-actions').hidden=false;
 if(step===0){$('#booking-content').innerHTML=`<p class="fine-print">Choose a service to explore. Timing is illustrative; no live availability is displayed.</p><fieldset style="border:0;padding:0;margin:18px 0"><legend class="eyebrow">CHOOSE YOUR SERVICE</legend><div class="booking-options">${services.map(s=>`<label class="option"><input type="radio" name="service" value="${s.id}" ${state.serviceId===s.id?'checked':''} required><span>${s.name}</span></label>`).join('')}</div></fieldset>${state.look?`<p class="fine-print">Your inspiration: ${safe(state.look)}</p>`:''}`;}
 if(step===1){const min=dateKey(new Date()),maxDate=new Date();maxDate.setDate(maxDate.getDate()+60);$('#booking-content').innerHTML=`<p class="fine-print">Times are examples based on listed hours. Sunday is closed. Choose a date within the next 60 days.</p><div class="form-row"><label class="field">Preferred date<input id="date" type="date" min="${min}" max="${dateKey(maxDate)}" value="${safe(state.date)}" required></label><label class="field">Example time<select id="time" required><option value="">Choose a date first</option></select></label></div><div class="form-row"><label class="field">Demo name<input id="name" autocomplete="off" maxlength="80" placeholder="Example: Alex Taylor" value="${safe(state.name)}" required></label><label class="field">Demo email<input id="email" type="email" autocomplete="off" maxlength="120" placeholder="alex@example.com" value="${safe(state.email)}" required></label></div><label class="field">What look do you have in mind? <span>(optional)</span><textarea id="notes" maxlength="500" rows="2" placeholder="Tell us about your inspiration…">${safe(state.notes||state.look)}</textarea></label><p class="fine-print">Please use fictional information. Nothing is sent or stored.</p>`;$('#date').addEventListener('change',()=>{state.date=$('#date').value;state.time='';updateTimes();});updateTimes();}
 if(step===2){const s=services.find(x=>x.id===state.serviceId);$('#booking-content').innerHTML=`<p class="fine-print">Review your demo visit. This does not reserve an appointment.</p><dl class="review-list"><div><dt>Service</dt><dd>${safe(s.name)}</dd></div><div><dt>Date</dt><dd>${safe(new Date(state.date+'T12:00:00').toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'}))}</dd></div><div><dt>Example time</dt><dd>${safe(new Date(state.date+'T'+state.time).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}))}</dd></div><div><dt>Demo guest</dt><dd>${safe(state.name)}</dd></div><div><dt>Demo email</dt><dd>${safe(state.email)}</dd></div><div><dt>Location</dt><dd>9344 Jones Road, Suite J</dd></div>${state.notes?`<div><dt>Style notes</dt><dd>${safe(state.notes)}</dd></div>`:''}</dl><p class="fine-print">Pricing, actual timing, and availability must be confirmed by the salon.</p>`;}
}
function updateTimes(){const d=state.date?new Date(state.date+'T00:00:00'):null;const s=services.find(x=>x.id===state.serviceId);const slots=d?slotsForDate(d,s.duration):[];$('#time').innerHTML=`<option value="">${!d?'Choose a date first':slots.length?'Select an example time':'No example times — choose another date'}</option>`+slots.map(t=>`<option value="${t.value}" ${t.value===state.time?'selected':''}>${t.label}</option>`).join('');$('#time').disabled=!slots.length;}
function capture(){if(step===0)state.serviceId=$('input[name=service]:checked',booking)?.value||'';if(step===1)for(const key of ['date','time','name','email','notes'])state[key]=$('#'+key).value.trim();}
$('#booking-back').addEventListener('click',()=>{capture();step=Math.max(0,step-1);renderStep();});
$('#booking-form').addEventListener('submit',e=>{e.preventDefault();capture();if(step===0&&!state.serviceId){$('#booking-error').textContent='Please choose a service.';return;}if(step===1){const d=new Date(state.date+'T00:00:00'),s=services.find(x=>x.id===state.serviceId);if(!slotsForDate(d,s.duration).some(t=>t.value===state.time)){$('#booking-error').textContent='Choose an example time during the listed opening hours.';return;}if(!state.name){$('#booking-error').textContent='Please enter a fictional demo name.';return;}}
 if(step<2){step++;renderStep();$('#booking-content input,#booking-content select',booking)?.focus();return;}$('#booking-content').innerHTML=`<div class="success-copy"><div class="complete-symbol">✦</div><h3>Your look is taking shape.</h3><p>You’ve completed the appointment walkthrough.<br><strong>No appointment was booked and no details were sent.</strong></p><p>Ready for a real visit? Call Hair by Four.</p><a class="button" href="tel:${salon.tel}">Call ${salon.phone} ↗</a><p class="fine-print">9344 Jones Road, Suite J · Houston, TX 77065</p><button type="button" class="text-link" data-close>Finish walkthrough</button></div>`;$('.booking-actions').hidden=true;$$('.steps li').forEach(x=>x.classList.remove('active'));$('.success-copy a').focus();});

// A local-only inspiration finder: no profiling, submission or storage.
function showFinder(){
 $('#finder-content').innerHTML=`<div class="finder-goals"><button data-goal="Cuts"><span>01</span><strong>A fresh shape</strong><small>A new silhouette, a sharper finish.</small><i>↗</i></button><button data-goal="Color"><span>02</span><strong>Richer color</strong><small>Soft brightness, warmth, dimension.</small><i>↗</i></button><button data-goal="Texture"><span>03</span><strong>More movement</strong><small>Volume, definition, natural character.</small><i>↗</i></button></div>`;
 openDialog($('#style-finder'));
}
document.addEventListener('click',e=>{
 if(e.target.closest('[data-finder]'))showFinder();
 const goal=e.target.closest('[data-goal]');
 if(goal){const matches=looks.filter(l=>l.type===goal.dataset.goal);$('#finder-content').innerHTML=`<p class="finder-result-intro">Your inspiration edit. Choose the look you’d like to discuss.</p><div class="finder-results">${matches.map(l=>`<button data-finder-look="${l.id}"><div class="photo panel-${l.panel}" role="img" aria-label="${l.name} concept inspiration"></div><strong>${l.name}</strong><small>${l.note}</small><span>Make this my inspiration ↗</span></button>`).join('')}</div><button class="text-link" data-finder-reset>← Explore another direction</button>`;$('#finder-content button')?.focus();}
 if(e.target.closest('[data-finder-reset]')){$('#style-finder').close();showFinder();}
 const chosen=e.target.closest('[data-finder-look]');
 if(chosen){const l=looks.find(x=>x.id===chosen.dataset.finderLook);$('#style-finder').close();startBooking(l.type==='Cuts'?'cut':l.type==='Color'?'color':'perm',l.name);}
});
